import{_ as n,o as e,c as t,ai as i}from"./chunks/framework.Ai2o9gNv.js";const s="/assets/mimo-creator-cover.Dvz88o6x.svg",a="/assets/image-20260527111258979.JrAmF5Xg.png",r="/assets/mimo-price-window.B9-uLL0H.svg",p="/assets/image-20260527111324107.BABXLJuT.png",l="/assets/mimo-tts-voice-lab.DIBoGmQ-.svg",m="/assets/ai-video-pipeline.DAvpSlku.svg",c="/assets/image-20260527110712146.DilndtS1.png",d="/assets/image-20260519145308924.Byq59aPt.png",g="/assets/image-20260527102911146.BriMfwZu.png",M="/assets/image-20260404153811993.DCT8eByA.png",f=JSON.parse('{"title":"小米 MiMo 发福利了？AI 视频创作者该动手了","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/小米 MiMo 发福利了？AI 视频创作者该动手了/小米 MiMo 发福利了？AI 视频创作者该动手了.md","filePath":"AI人工智能/小米 MiMo 发福利了？AI 视频创作者该动手了/小米 MiMo 发福利了？AI 视频创作者该动手了.md","lastUpdated":1779851685000,"__rawMarkdown":"# 小米 MiMo 发福利了？AI 视频创作者该动手了\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> 2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户800+、鸿蒙免费课程2套、付费课程1套；\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n> **一句话结论：**MiMo-V2.5 降价不是简单的“模型更便宜了”，而是让 **Codex 写脚本 + HyperFrames 生成视频 + MiMo TTS 配音 + 字幕生成** 这类组合工作流，变得更适合个人创作者折腾。\\n\\n![小米 MiMo 发福利了？AI 视频创作者该动手了](./assets/mimo-creator-cover.svg)\\n\\n今天大模型圈一个值得关注的消息：**小米 MiMo-V2.5 系列降价了。**\\n\\n根据小米 MiMo 开放平台公告，MiMo-V2.5 系列价格最高下调 **99%**，Token Plan 额度提升 **5 到 8 倍**，生效时间是 **2026 年 5 月 27 日 00:00，GMT+8**。\\n\\n如果只把它看成“大模型又卷价格”，其实有点可惜。对内容创作者来说，更关键的是：**脚本、配音、字幕、视频画面这些环节，正在被串成一条低成本生产线。**\\n\\n![](assets/image-20260527111258979.png)\\n\\n![MiMo 降价窗口：反复试错成本下降](./assets/mimo-price-window.svg)\\n\\n---\\n\\n## 真正便宜的不是聊天，而是“反复试错”\\n\\n普通用户一天问几十次，降价体感不会特别强。\\n\\n但**视频创作者**不一样。一条教程视频背后，可能要反复生成：\\n\\n- 标题和开头\\n- 口播脚本\\n- 分镜结构\\n- 配音版本\\n- 字幕文案\\n- 视频模板\\n\\n以前贵的是“每改一次都要成本”。现在 MiMo 文本模型降价，TTS 又在官方计费页显示 **限时免费**，创作者就可以更大胆地试多个版本。\\n\\n*这才是这次降价最值得关注的地方：AI 内容生产开始从“偶尔调用”，变成“流程调用”。*\\n\\n---\\n\\n## 小米 TTS 声音生产工具\\n\\n>  目前可以直接通过调用小米TTS的方式来动态生成语音，这个步骤你可以交给你的AI去操作即可>\\n>\\n> https://platform.xiaomimimo.com/docs/zh-CN/usage-guide/speech-synthesis-v2.5\\n\\n![](assets/image-20260527111324107.png)\\n\\n\\n\\n小米 MiMo-V2.5-TTS 系列目前主要有三类：\\n\\n| 模型 | 模型 ID | 用途 |\\n| --- | --- | --- |\\n| MiMo-V2.5-TTS | `mimo-v2.5-tts` | 使用内置音色生成语音 |\\n| VoiceDesign | `mimo-v2.5-tts-voicedesign` | 用文字描述定制声音 |\\n| VoiceClone | `mimo-v2.5-tts-voiceclone` | 基于音频样本克隆声音 |\\n\\n![MiMo TTS 声音实验室](./assets/mimo-tts-voice-lab.svg)\\n\\n它的意义不只是“把文字读出来”，而是让视频创作者可以控制：\\n\\n- **语速**\\n- **情绪**\\n- **角色感**\\n- **方言/风格**\\n- **系列内容的统一音色**\\n\\n比如做教程视频，你可能需要的是“清晰、稳定、不抢内容”的声音；做短视频口播，则可能需要更快节奏、更强重点。TTS 能调风格，内容生产的空间就大很多。\\n\\n---\\n\\n## Codex + HyperFrames + MiMo TTS：组合出视频、音频、字幕\\n\\n把几个工具串起来，流程大概是这样：\\n\\n![AI 视频流水线：从选题到成片](./assets/ai-video-pipeline.svg)\\n\\n这条链路里：\\n\\n- **Codex**：负责写脚本、拆分镜、生成代码和配置；\\n- **HyperFrames**：负责把 HTML/CSS/JS 渲染成视频画面；\\n- **MiMo TTS**：负责把文案变成旁白音频；\\n- **字幕**：可先由脚本生成，再按音频校准。\\n\\n这套组合工作流的目标产物是：**视频 + 音频 + 字幕**。\\n\\n注意，这不是某一家平台提供的“官方一键生成功能”，而是把多个工具按生产流程串起来。\\n\\n这不是科幻，也不是 PPT 式概念。对标准化教程、知识卡片、工具介绍类视频来说，这套流程已经很适合落地。\\n\\n使用方式：\\n\\n打开你的 codex终端，然后输入提示词 \\n\\n```\\n使用 HyperFrames 这个skill  和 MiMo TTS 帮我  xxxxx\\n\\n```\\n\\n万少的视频就是这样产生的；\\n\\n![](assets/image-20260527110712146.png)\\n\\n---\\n\\n## 一个例子：万少的 Claude Code 入门教程\\n\\n![](assets/image-20260519145308924.png)\\n\\n比如万少发布在 B 站的合集：\\n\\n**《万少的 claude code 入门教程》**  \\n<https://www.bilibili.com/video/BV14jGR6PEJv/>\\n\\n![](assets/image-20260527102911146.png)\\n\\n这个合集由 **HarmonyOS-万少** 发布，合集名为 **《万少的claude code 入门教程》**，当前显示 **15 个分集**，内容覆盖安装、模型配置、VS Code 插件、权限模式、Skill、MCP、SubAgents、Hooks、Plugins、AgentTeams 等主题。\\n\\n这类内容特别适合 AI 视频流水线，因为它有几个特点：\\n\\n1. **结构固定**：每集讲一个知识点；\\n2. **画面可复用**：标题页、代码页、步骤页都能模板化；\\n3. **配音要统一**：系列教程最好保持同一个声音风格；\\n4. **字幕天然可生成**：脚本就是字幕的基础。\\n\\n换句话说，AI 不是替你“随便生成视频”，而是替你处理重复劳动：排版、配音、字幕、模板化渲染。\\n\\n\\n\\n---\\n\\n## 最后\\n\\n这次 MiMo 降价，真正值得盯住的不是“又便宜了多少”，而是它给个人创作者打开了一个窗口：\\n\\n> *一个人，也可以用工程化方式生产技术视频。*\\n\\n当 Codex 负责脚本和代码，HyperFrames 负责画面，MiMo TTS 负责声音，字幕可从脚本生成并校准，AI 视频的门槛就不再是“剪辑软件有多熟”，而是：\\n\\n**你能不能把一个知识点讲清楚、讲持续、讲成系列。**\\n\\n这才是 MiMo 发福利背后，最值得技术创作者动手的地方。\\n\\n---\\n\\n\\n\\n## 参考来源\\n\\n- 小米 MiMo 计费页：<https://platform.xiaomimimo.com/docs/en-US/price/pay-as-you-go>\\n- 小米 MiMo-V2.5-TTS 文档：<https://platform.xiaomimimo.com/docs/en-US/usage-guide/speech-synthesis-v2.5>\\n- 小米 MiMo Claude Code 配置文档：<https://platform.xiaomimimo.com/docs/en-US/integration/claudecode>\\n- 小米 MiMo V2.5 价格公告页：<https://platform.xiaomimimo.com/docs/en-US/news/v2.5-price-update>\\n- B 站合集链接：<https://www.bilibili.com/video/BV14jGR6PEJv/>\\n\\n\\n\\n\\n\\n\\n\\n万少建立了一个专门讨论AI的微信群，大家可以互相交流和分享关于AI生态的资讯消息。\\n\\n目前人已经超过400人了，私聊我进群。\\n\\n关注我，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n\\n\\n\\n\\n![](assets/image-20260404153811993.DCT8eByA.png)"}'),h={name:"AI人工智能/小米 MiMo 发福利了？AI 视频创作者该动手了/小米 MiMo 发福利了？AI 视频创作者该动手了.md"};function u(T,o,b,_,S,v){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="小米-mimo-发福利了-ai-视频创作者该动手了" tabindex="-1">小米 MiMo 发福利了？AI 视频创作者该动手了 <a class="header-anchor" href="#小米-mimo-发福利了-ai-视频创作者该动手了" aria-label="Permalink to &quot;小米 MiMo 发福利了？AI 视频创作者该动手了&quot;">​</a></h1><blockquote><p>万少：华为HDE、鸿蒙极客</p><p>个人主页：<a href="https://blog.zbztb.cn/" target="_blank" rel="noreferrer">https://blog.zbztb.cn/</a></p><p>2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户800+、鸿蒙免费课程2套、付费课程1套；</p><p>如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。</p></blockquote><blockquote><p>**一句话结论：**MiMo-V2.5 降价不是简单的“模型更便宜了”，而是让 <strong>Codex 写脚本 + HyperFrames 生成视频 + MiMo TTS 配音 + 字幕生成</strong> 这类组合工作流，变得更适合个人创作者折腾。</p></blockquote><p><img src="'+s+'" alt="小米 MiMo 发福利了？AI 视频创作者该动手了"></p><p>今天大模型圈一个值得关注的消息：<strong>小米 MiMo-V2.5 系列降价了。</strong></p><p>根据小米 MiMo 开放平台公告，MiMo-V2.5 系列价格最高下调 <strong>99%</strong>，Token Plan 额度提升 <strong>5 到 8 倍</strong>，生效时间是 <strong>2026 年 5 月 27 日 00:00，GMT+8</strong>。</p><p>如果只把它看成“大模型又卷价格”，其实有点可惜。对内容创作者来说，更关键的是：<strong>脚本、配音、字幕、视频画面这些环节，正在被串成一条低成本生产线。</strong></p><p><img src="'+a+'" alt=""></p><p><img src="'+r+'" alt="MiMo 降价窗口：反复试错成本下降"></p><hr><h2 id="真正便宜的不是聊天-而是-反复试错" tabindex="-1">真正便宜的不是聊天，而是“反复试错” <a class="header-anchor" href="#真正便宜的不是聊天-而是-反复试错" aria-label="Permalink to &quot;真正便宜的不是聊天，而是“反复试错”&quot;">​</a></h2><p>普通用户一天问几十次，降价体感不会特别强。</p><p>但<strong>视频创作者</strong>不一样。一条教程视频背后，可能要反复生成：</p><ul><li>标题和开头</li><li>口播脚本</li><li>分镜结构</li><li>配音版本</li><li>字幕文案</li><li>视频模板</li></ul><p>以前贵的是“每改一次都要成本”。现在 MiMo 文本模型降价，TTS 又在官方计费页显示 <strong>限时免费</strong>，创作者就可以更大胆地试多个版本。</p><p><em>这才是这次降价最值得关注的地方：AI 内容生产开始从“偶尔调用”，变成“流程调用”。</em></p><hr><h2 id="小米-tts-声音生产工具" tabindex="-1">小米 TTS 声音生产工具 <a class="header-anchor" href="#小米-tts-声音生产工具" aria-label="Permalink to &quot;小米 TTS 声音生产工具&quot;">​</a></h2><blockquote><p>目前可以直接通过调用小米TTS的方式来动态生成语音，这个步骤你可以交给你的AI去操作即可&gt;</p><p><a href="https://platform.xiaomimimo.com/docs/zh-CN/usage-guide/speech-synthesis-v2.5" target="_blank" rel="noreferrer">https://platform.xiaomimimo.com/docs/zh-CN/usage-guide/speech-synthesis-v2.5</a></p></blockquote><p><img src="'+p+'" alt=""></p><p>小米 MiMo-V2.5-TTS 系列目前主要有三类：</p><table tabindex="0"><thead><tr><th>模型</th><th>模型 ID</th><th>用途</th></tr></thead><tbody><tr><td>MiMo-V2.5-TTS</td><td><code>mimo-v2.5-tts</code></td><td>使用内置音色生成语音</td></tr><tr><td>VoiceDesign</td><td><code>mimo-v2.5-tts-voicedesign</code></td><td>用文字描述定制声音</td></tr><tr><td>VoiceClone</td><td><code>mimo-v2.5-tts-voiceclone</code></td><td>基于音频样本克隆声音</td></tr></tbody></table><p><img src="'+l+'" alt="MiMo TTS 声音实验室"></p><p>它的意义不只是“把文字读出来”，而是让视频创作者可以控制：</p><ul><li><strong>语速</strong></li><li><strong>情绪</strong></li><li><strong>角色感</strong></li><li><strong>方言/风格</strong></li><li><strong>系列内容的统一音色</strong></li></ul><p>比如做教程视频，你可能需要的是“清晰、稳定、不抢内容”的声音；做短视频口播，则可能需要更快节奏、更强重点。TTS 能调风格，内容生产的空间就大很多。</p><hr><h2 id="codex-hyperframes-mimo-tts-组合出视频、音频、字幕" tabindex="-1">Codex + HyperFrames + MiMo TTS：组合出视频、音频、字幕 <a class="header-anchor" href="#codex-hyperframes-mimo-tts-组合出视频、音频、字幕" aria-label="Permalink to &quot;Codex + HyperFrames + MiMo TTS：组合出视频、音频、字幕&quot;">​</a></h2><p>把几个工具串起来，流程大概是这样：</p><p><img src="'+m+'" alt="AI 视频流水线：从选题到成片"></p><p>这条链路里：</p><ul><li><strong>Codex</strong>：负责写脚本、拆分镜、生成代码和配置；</li><li><strong>HyperFrames</strong>：负责把 HTML/CSS/JS 渲染成视频画面；</li><li><strong>MiMo TTS</strong>：负责把文案变成旁白音频；</li><li><strong>字幕</strong>：可先由脚本生成，再按音频校准。</li></ul><p>这套组合工作流的目标产物是：<strong>视频 + 音频 + 字幕</strong>。</p><p>注意，这不是某一家平台提供的“官方一键生成功能”，而是把多个工具按生产流程串起来。</p><p>这不是科幻，也不是 PPT 式概念。对标准化教程、知识卡片、工具介绍类视频来说，这套流程已经很适合落地。</p><p>使用方式：</p><p>打开你的 codex终端，然后输入提示词</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 HyperFrames 这个skill  和 MiMo TTS 帮我  xxxxx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>万少的视频就是这样产生的；</p><p><img src="'+c+'" alt=""></p><hr><h2 id="一个例子-万少的-claude-code-入门教程" tabindex="-1">一个例子：万少的 Claude Code 入门教程 <a class="header-anchor" href="#一个例子-万少的-claude-code-入门教程" aria-label="Permalink to &quot;一个例子：万少的 Claude Code 入门教程&quot;">​</a></h2><p><img src="'+d+'" alt=""></p><p>比如万少发布在 B 站的合集：</p><p><strong>《万少的 claude code 入门教程》</strong><br><a href="https://www.bilibili.com/video/BV14jGR6PEJv/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV14jGR6PEJv/</a></p><p><img src="'+g+'" alt=""></p><p>这个合集由 <strong>HarmonyOS-万少</strong> 发布，合集名为 <strong>《万少的claude code 入门教程》</strong>，当前显示 <strong>15 个分集</strong>，内容覆盖安装、模型配置、VS Code 插件、权限模式、Skill、MCP、SubAgents、Hooks、Plugins、AgentTeams 等主题。</p><p>这类内容特别适合 AI 视频流水线，因为它有几个特点：</p><ol><li><strong>结构固定</strong>：每集讲一个知识点；</li><li><strong>画面可复用</strong>：标题页、代码页、步骤页都能模板化；</li><li><strong>配音要统一</strong>：系列教程最好保持同一个声音风格；</li><li><strong>字幕天然可生成</strong>：脚本就是字幕的基础。</li></ol><p>换句话说，AI 不是替你“随便生成视频”，而是替你处理重复劳动：排版、配音、字幕、模板化渲染。</p><hr><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>这次 MiMo 降价，真正值得盯住的不是“又便宜了多少”，而是它给个人创作者打开了一个窗口：</p><blockquote><p><em>一个人，也可以用工程化方式生产技术视频。</em></p></blockquote><p>当 Codex 负责脚本和代码，HyperFrames 负责画面，MiMo TTS 负责声音，字幕可从脚本生成并校准，AI 视频的门槛就不再是“剪辑软件有多熟”，而是：</p><p><strong>你能不能把一个知识点讲清楚、讲持续、讲成系列。</strong></p><p>这才是 MiMo 发福利背后，最值得技术创作者动手的地方。</p><hr><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>小米 MiMo 计费页：<a href="https://platform.xiaomimimo.com/docs/en-US/price/pay-as-you-go" target="_blank" rel="noreferrer">https://platform.xiaomimimo.com/docs/en-US/price/pay-as-you-go</a></li><li>小米 MiMo-V2.5-TTS 文档：<a href="https://platform.xiaomimimo.com/docs/en-US/usage-guide/speech-synthesis-v2.5" target="_blank" rel="noreferrer">https://platform.xiaomimimo.com/docs/en-US/usage-guide/speech-synthesis-v2.5</a></li><li>小米 MiMo Claude Code 配置文档：<a href="https://platform.xiaomimimo.com/docs/en-US/integration/claudecode" target="_blank" rel="noreferrer">https://platform.xiaomimimo.com/docs/en-US/integration/claudecode</a></li><li>小米 MiMo V2.5 价格公告页：<a href="https://platform.xiaomimimo.com/docs/en-US/news/v2.5-price-update" target="_blank" rel="noreferrer">https://platform.xiaomimimo.com/docs/en-US/news/v2.5-price-update</a></li><li>B 站合集链接：<a href="https://www.bilibili.com/video/BV14jGR6PEJv/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV14jGR6PEJv/</a></li></ul><p>万少建立了一个专门讨论AI的微信群，大家可以互相交流和分享关于AI生态的资讯消息。</p><p>目前人已经超过400人了，私聊我进群。</p><p>关注我，持续分享鸿蒙开发 + AI 提效的实战技巧。</p><p><img src="'+M+'" alt=""></p>',64)])])}const A=n(h,[["render",u]]);export{f as __pageData,A as default};
